      </div>

      <div class="panel">

        <div class="panel-header">
          <div class="panel-title">Response</div>

          <div class="response-meta">
            <div class="meta-box" id="statusBox">Status: -</div>
            <div class="meta-box" id="timeBox">0 ms</div>
            <div class="meta-box" id="sizeBox">0 B</div>
