          </div>

          <div id="responseHeadersView" class="hidden">
            <pre id="responseHeaders"></pre>
          </div>

          <div id="responsePreviewView" class="hidden">
            <iframe id="previewFrame" style="width:100%;height:500px;border:1px solid var(--border);border-radius:12px;background:white;"></iframe>
          </div>
        </div>

      </div>

    </div>

  </div>

</div>

<div class="toast" id="toast"></div>

<script>
const tabs = document.querySelectorAll('.tab');
const responseTabs = document.querySelectorAll('.response-tab');

const sendBtn = document.getElementById('sendBtn');
const cancelBtn = document.getElementById('cancelBtn');
const beautifyBtn = document.getElementById('beautifyBtn');
const copyCurlBtn = document.getElementById('copyCurlBtn');

const methodEl = document.getElementById('method');
const urlEl = document.getElementById('url');
const bodyEl = document.getElementById('body');

const responseBody = document.getElementById('responseBody');
const responseHeaders = document.getElementById('responseHeaders');

const statusBox = document.getElementById('statusBox');
const timeBox = document.getElementById('timeBox');
const sizeBox = document.getElementById('sizeBox');

const previewFrame = document.getElementById('previewFrame');
const historyList = document.getElementById('historyList');

let controller = null;
let darkMode = true;

/* -----------------------------
   TOAST
----------------------------- */
function toast(message) {
  const el = document.getElementById('toast');

  el.innerText = message;
  el.style.display = 'block';

  clearTimeout(window.toastTimer);

  window.toastTimer = setTimeout(() => {
    el.style.display = 'none';
  }, 2500);
}

/* -----------------------------
   TAB SYSTEM
----------------------------- */
tabs.forEach(tab => {
  tab.addEventListener('click', () => {
    tabs.forEach(t => t.classList.remove('active'));

    tab.classList.add('active');

    const target = tab.dataset.tab;

    document.querySelectorAll('.tab-content').forEach(content => {
      content.classList.add('hidden');
    });

    document.getElementById(target + 'Tab').classList.remove('hidden');
  });
});

/* -----------------------------
   RESPONSE TAB
----------------------------- */
responseTabs.forEach(tab => {
  tab.addEventListener('click', () => {
    responseTabs.forEach(t => t.classList.remove('active'));

    tab.classList.add('active');

    const target = tab.dataset.response;

    document
      .getElementById('responseBodyView')
      .classList.add('hidden');

    document
      .getElementById('responseHeadersView')
      .classList.add('hidden');

    document
      .getElementById('responsePreviewView')
      .classList.add('hidden');

    document
      .getElementById(
        'response' +
        target.charAt(0).toUpperCase() +
        target.slice(1) +
        'View'
      )
      .classList.remove('hidden');
  });
});

/* -----------------------------
   PARAMS
----------------------------- */
function addParam(key = '', value = '') {
  const container = document.getElementById('paramsContainer');

  const row = document.createElement('div');

  row.className = 'key-value';

  row.innerHTML = `
    <input placeholder="Key" value="${key}">
    <input placeholder="Value" value="${value}">
    <button class="secondary">×</button>
  `;

  row.querySelector('button').onclick = () => row.remove();

  container.appendChild(row);
}

/* -----------------------------
   HEADERS
----------------------------- */
function addHeader(key = '', value = '') {
  const container = document.getElementById('headersContainer');

  const row = document.createElement('div');

  row.className = 'key-value';

  row.innerHTML = `
    <input placeholder="Header" value="${key}">
    <input placeholder="Value" value="${value}">
    <button class="secondary">×</button>
  `;

  row.querySelector('button').onclick = () => row.remove();

  container.appendChild(row);
}

/* -----------------------------
   COLLECT KEY VALUE
----------------------------- */
function collectKeyValues(id) {
  const result = {};

  document.querySelectorAll(`#${id} .key-value`).forEach(row => {
    const inputs = row.querySelectorAll('input');

    const key = inputs[0].value.trim();
    const value = inputs[1].value.trim();

    if (key) {
      result[key] = value;
    }
  });

  return result;
}

/* -----------------------------
   AUTH GENERATOR
----------------------------- */
function generateAuth(headers) {
  const type = document.getElementById('authType').value;

  if (type === 'bearer') {
    const token = document.getElementById('bearerToken')?.value;

    if (token) {
      headers['Authorization'] = 'Bearer ' + token;
    }
  }

  if (type === 'basic') {
    const user = document.getElementById('basicUser')?.value || '';
    const pass = document.getElementById('basicPass')?.value || '';

    headers['Authorization'] =
      'Basic ' + btoa(user + ':' + pass);
  }

  if (type === 'apikey') {
    const key = document.getElementById('apiKeyName')?.value;
    const value = document.getElementById('apiKeyValue')?.value;

    if (key) {
      headers[key] = value;
    }
  }
}

/* -----------------------------
   AUTH UI
----------------------------- */
document.getElementById('authType').onchange = e => {
  const value = e.target.value;

  const fields = document.getElementById('authFields');

  if (value === 'none') {
    fields.innerHTML = '';
  }

  if (value === 'bearer') {
    fields.innerHTML = `
      <input id="bearerToken" placeholder="Bearer Token">
    `;
  }

  if (value === 'basic') {
    fields.innerHTML = `
      <input id="basicUser" placeholder="Username" style="margin-bottom:10px;">
      <input id="basicPass" type="password" placeholder="Password">
    `;
  }

  if (value === 'apikey') {
    fields.innerHTML = `
      <input id="apiKeyName" placeholder="Header Name" style="margin-bottom:10px;">
      <input id="apiKeyValue" placeholder="API Key">
    `;
  }
};

/* -----------------------------
   SEND REQUEST
----------------------------- */
sendBtn.onclick = async () => {
  const method = methodEl.value;
  const rawUrl = urlEl.value.trim();

  if (!rawUrl) {
    toast('URL required');
    return;
  }

  const headers = collectKeyValues('headersContainer');
  const params = collectKeyValues('paramsContainer');

  generateAuth(headers);

  const url = new URL(rawUrl);

  Object.entries(params).forEach(([k, v]) => {
    url.searchParams.set(k, v);
  });

  const options = {
    method,
    headers
  };

  const body = bodyEl.value.trim();

  if (body && !['GET', 'HEAD'].includes(method)) {
    options.body = body;
  }

  controller = new AbortController();

  options.signal = controller.signal;

  sendBtn.disabled = true;
  sendBtn.innerText = 'Sending...';

  const started = performance.now();

  try {
    const res = await fetch(url, options);

    const elapsed =
      Math.round(performance.now() - started);

    const text = await res.text();

    const size = new Blob([text]).size;

    statusBox.innerHTML = `
      Status:
      <span class="${res.ok ? 'status-ok' : 'status-error'}">
        ${res.status}
      </span>
    `;

    timeBox.innerText = elapsed + ' ms';
    sizeBox.innerText = size + ' B';

    /* headers */
    let headerText = '';

    res.headers.forEach((value, key) => {
      headerText += key + ': ' + value + '\n';
    });

    responseHeaders.innerText = headerText;

    /* body */
    try {
      const json = JSON.parse(text);

      responseBody.innerText =
        JSON.stringify(json, null, 2);
    } catch {
      responseBody.innerText = text;
    }

    /* preview */
    const contentType =
      res.headers.get('content-type') || '';

    if (contentType.includes('text/html')) {
      previewFrame.srcdoc = text;
    }

    saveHistory(method, rawUrl);

    toast('Request success');
  } catch (err) {
    responseBody.innerText = err.message;

    toast('Request failed');
  }

  sendBtn.disabled = false;
  sendBtn.innerText = 'Send';
};

/* -----------------------------
   CANCEL REQUEST
----------------------------- */
cancelBtn.onclick = () => {
  if (controller) {
    controller.abort();

    toast('Request cancelled');
  }
};

/* -----------------------------
   BEAUTIFY JSON
----------------------------- */
beautifyBtn.onclick = () => {
  try {
    const parsed = JSON.parse(bodyEl.value);

    bodyEl.value =
      JSON.stringify(parsed, null, 2);

    toast('Beautified');
  } catch {
    toast('Invalid JSON');
  }
};

/* -----------------------------
   COPY CURL
----------------------------- */
copyCurlBtn.onclick = async () => {
  const method = methodEl.value;
  const url = urlEl.value;

  const headers = collectKeyValues('headersContainer');

  let curl = `curl -X ${method} "${url}"`;

  Object.entries(headers).forEach(([k, v]) => {
    curl += ` \\
  -H "${k}: ${v}"`;
  });

  const body = bodyEl.value.trim();

  if (body) {
    curl += ` \\
  -d '${body.replace(/'/g, "\\'")}'`;
  }

  await navigator.clipboard.writeText(curl);

  toast('cURL copied');
};

/* -----------------------------
   HISTORY
----------------------------- */
function saveHistory(method, url) {
  let history =
    JSON.parse(
      localStorage.getItem('lxrest-history') || '[]'
    );

  history.unshift({
    method,
    url,
    time: Date.now()
  });

  history = history.slice(0, 15);

  localStorage.setItem(
    'lxrest-history',
    JSON.stringify(history)
  );

  renderHistory();
}

function renderHistory() {
  const history =
    JSON.parse(
      localStorage.getItem('lxrest-history') || '[]'
    );

  historyList.innerHTML = '';

  history.forEach(item => {
    const div = document.createElement('div');

    div.className = 'collection-item';

    div.innerHTML = `
      <div style="font-size:12px;font-weight:600;">
        ${item.method}
      </div>

      <div style="
        font-size:11px;
        color:var(--muted);
        overflow:hidden;
        text-overflow:ellipsis;
      ">
        ${item.url}
      </div>
    `;

    div.onclick = () => {
      methodEl.value = item.method;
      urlEl.value = item.url;
    };

    historyList.appendChild(div);
  });
}

/* -----------------------------
   THEME TOGGLE
----------------------------- */
document.getElementById('themeBtn').onclick = () => {
  darkMode = !darkMode;

  if (!darkMode) {
    document.documentElement.style.setProperty(
      '--panel',
      '#ffffff'
    );

    document.documentElement.style.setProperty(
      '--text',
      '#0f172a'
    );

    toast('Light mode');
  } else {
    document.documentElement.style.setProperty(
      '--panel',
      '#111827'
    );

    document.documentElement.style.setProperty(
      '--text',
      '#e5e7eb'
    );

    toast('Dark mode');
  }
};

/* -----------------------------
   AUTOSAVE
----------------------------- */
['url', 'body', 'method'].forEach(id => {
  document
    .getElementById(id)
    .addEventListener('input', () => {
      localStorage.setItem(
        'lxrest-' + id,
        document.getElementById(id).value
      );
    });
});

window.addEventListener('load', () => {
  ['url', 'body', 'method'].forEach(id => {
    const value =
      localStorage.getItem('lxrest-' + id);

    if (value !== null) {
      document.getElementById(id).value = value;
    }
  });

  renderHistory();
});

/* -----------------------------
   SHORTCUT
----------------------------- */
window.addEventListener('keydown', e => {
  if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
    sendBtn.click();
  }
});

/* -----------------------------
   INIT
----------------------------- */
addHeader('Content-Type', 'application/json');
addParam();

</script>
/* -----------------------------
   IMPORT CURL
----------------------------- */
function importCurl(curl) {
  try {
    const methodMatch =
      curl.match(/-X\\s+(\\w+)/i);

    const urlMatch =
      curl.match(/(https?:\\/\\/[^\\s\"']+)/i);

    methodEl.value =
      methodMatch?.[1] || 'GET';

    urlEl.value =
      urlMatch?.[1] || '';

    /* headers */
    document.getElementById(
      'headersContainer'
    ).innerHTML = '';

    const headerRegex =
      /-H\\s+[\"']([^:]+):\\s*(.+?)[\"']/g;

    let match;

    while ((match = headerRegex.exec(curl))) {
      addHeader(match[1], match[2]);
    }

    /* body */
    const bodyMatch =
      curl.match(/-d\\s+[\"']([\\s\\S]*?)[\"']/);

    if (bodyMatch) {
      bodyEl.value = bodyMatch[1];
    }

    toast('cURL imported');
  } catch {
    toast('Invalid cURL');
  }
}

/* -----------------------------
   DOWNLOAD RESPONSE
----------------------------- */
function downloadResponse() {
  const content = responseBody.innerText;

  const blob = new Blob(
    [content],
    { type: 'text/plain' }
  );

  const url =
    URL.createObjectURL(blob);

  const a =
    document.createElement('a');

  a.href = url;

  a.download =
    'response.txt';

  a.click();

  URL.revokeObjectURL(url);

  toast('Downloaded');
}

/* -----------------------------
   COPY RESPONSE
----------------------------- */
async function copyResponse() {
  await navigator.clipboard.writeText(
    responseBody.innerText
  );

  toast('Response copied');
}

/* -----------------------------
   CLEAR REQUEST
----------------------------- */
function clearRequest() {
  urlEl.value = '';
  bodyEl.value = '';

  document.getElementById(
    'paramsContainer'
  ).innerHTML = '';

  document.getElementById(
    'headersContainer'
  ).innerHTML = '';

  addHeader(
    'Content-Type',
    'application/json'
  );

  addParam();

  toast('Request cleared');
}

/* -----------------------------
   CLEAR HISTORY
----------------------------- */
function clearHistory() {
  localStorage.removeItem(
    'lxrest-history'
  );

  renderHistory();

  toast('History cleared');
}

/* -----------------------------
   EXPORT HISTORY
----------------------------- */
function exportHistory() {
  const history =
    localStorage.getItem(
      'lxrest-history'
    ) || '[]';

  const blob = new Blob(
    [history],
    { type: 'application/json' }
  );

  const url =
    URL.createObjectURL(blob);

  const a =
    document.createElement('a');

  a.href = url;

  a.download =
    'lxrest-history.json';

  a.click();

  URL.revokeObjectURL(url);

  toast('History exported');
}

/* -----------------------------
   IMPORT HISTORY
----------------------------- */
function importHistory(file) {
  const reader = new FileReader();

  reader.onload = e => {
    try {
      JSON.parse(e.target.result);

      localStorage.setItem(
        'lxrest-history',
        e.target.result
      );

      renderHistory();

      toast('History imported');
    } catch {
      toast('Invalid history file');
    }
  };

  reader.readAsText(file);
}

/* -----------------------------
   ENVIRONMENT VARIABLES
----------------------------- */
const env = {
  api: 'https://jsonplaceholder.typicode.com',
  auth: 'sample-token'
};

function applyEnvironment(text) {
  return text.replace(
    /\\{\\{(.*?)\\}\\}/g,
    (_, key) => env[key.trim()] || ''
  );
}

/* -----------------------------
   METHOD COLOR
----------------------------- */
methodEl.addEventListener(
  'change',
  () => {
    const method =
      methodEl.value;

    const colors = {
      GET: '#22c55e',
      POST: '#3b82f6',
      PUT: '#f59e0b',
      PATCH: '#eab308',
      DELETE: '#ef4444',
      OPTIONS: '#8b5cf6'
    };

    methodEl.style.color =
      colors[method] || '#fff';
  }
);

/* -----------------------------
   SEARCH RESPONSE
----------------------------- */
function searchResponse(keyword) {
  const text =
    responseBody.innerText;

  if (!keyword) {
    responseBody.innerHTML =
      text;

    return;
  }

  const regex =
    new RegExp(keyword, 'gi');

  responseBody.innerHTML =
    text.replace(
      regex,
      match =>
        `<mark>${match}</mark>`
    );
}

/* -----------------------------
   REQUEST TIMER
----------------------------- */
let requestCount = 0;

function updateRequestCounter() {
  requestCount++;

  document.title =
    `LxREST (${requestCount})`;
}

/* -----------------------------
   NETWORK STATUS
----------------------------- */
window.addEventListener(
  'online',
  () => toast('Online')
);

window.addEventListener(
  'offline',
  () => toast('Offline')
);

/* -----------------------------
   DRAG DROP IMPORT
----------------------------- */
window.addEventListener(
  'dragover',
  e => {
    e.preventDefault();
  }
);

window.addEventListener(
  'drop',
  e => {
    e.preventDefault();

    const file =
      e.dataTransfer.files[0];

    if (!file) return;

    const reader =
      new FileReader();

    reader.onload = ev => {
      bodyEl.value =
        ev.target.result;

      toast('File imported');
    };

    reader.readAsText(file);
  }
);

/* -----------------------------
   RESPONSE FORMATTER
----------------------------- */
function formatBytes(bytes) {
  if (bytes < 1024)
    return bytes + ' B';

  if (bytes < 1024 * 1024)
    return (
      (bytes / 1024).toFixed(2) +
      ' KB'
    );

  return (
    (bytes / 1024 / 1024).toFixed(
      2
    ) + ' MB'
  );
}

/* -----------------------------
   IMAGE PREVIEW
----------------------------- */
function renderPreview(
  text,
  contentType
) {
  if (
    contentType.includes(
      'text/html'
    )
  ) {
    previewFrame.srcdoc = text;
  }

  if (
    contentType.includes(
      'image/'
    )
  ) {
    previewFrame.srcdoc = `
      <img
        src="data:${contentType};base64,${btoa(text)}"
        style="max-width:100%;padding:20px;"
      >
    `;
  }
}

/* -----------------------------
   URL VALIDATOR
----------------------------- */
function isValidURL(url) {
  try {
    new URL(url);

    return true;
  } catch {
    return false;
  }
}

/* -----------------------------
   AUTO JSON HEADER
----------------------------- */
bodyEl.addEventListener(
  'input',
  () => {
    try {
      JSON.parse(bodyEl.value);

      let found = false;

      document.querySelectorAll(
        '#headersContainer .key-value'
      ).forEach(row => {
        const inputs =
          row.querySelectorAll(
            'input'
          );

        if (
          inputs[0].value ===
          'Content-Type'
        ) {
          inputs[1].value =
            'application/json';

          found = true;
        }
      });

      if (!found) {
        addHeader(
          'Content-Type',
          'application/json'
        );
      }
    } catch {}
  }
);

/* -----------------------------
   AUTO RESIZE BODY
----------------------------- */
bodyEl.addEventListener(
  'input',
  () => {
    bodyEl.style.height =
      'auto';

    bodyEl.style.height =
      bodyEl.scrollHeight + 'px';
  }
);

/* -----------------------------
   ESCAPE HTML
----------------------------- */
function escapeHTML(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/* -----------------------------
   JSON SYNTAX HIGHLIGHT
----------------------------- */
function syntaxHighlight(json) {
  json = escapeHTML(json);

  return json.replace(
    /(\"(\\\\u[a-zA-Z0-9]{4}|\\\\[^u]|[^\\\\\"])*\"(\\s*:)?|\\b(true|false|null)\\b|-?\\d+(?:\\.\\d*)?(?:[eE][+\\-]?\\d+)?)/g,
    match => {
      let cls = '#e5e7eb';

      if (/^\"/.test(match)) {
        cls = /:$/.test(match)
          ? '#93c5fd'
          : '#86efac';
      } else if (
        /true|false/.test(match)
      ) {
        cls = '#fca5a5';
      } else if (/null/.test(match)) {
        cls = '#c4b5fd';
      } else {
        cls = '#fdba74';
      }

      return `
        <span style="color:${cls}">
          ${match}
        </span>
      `;
    }
  );
}

/* -----------------------------
   JSON VIEWER
----------------------------- */
function renderJSON(text) {
  try {
    const formatted =
      JSON.stringify(
        JSON.parse(text),
        null,
        2
      );

    responseBody.innerHTML =
      syntaxHighlight(formatted);
  } catch {
    responseBody.innerText =
      text;
  }
}

/* -----------------------------
   SHORTCUTS
----------------------------- */
window.addEventListener(
  'keydown',
  e => {
    if (
      (e.ctrlKey || e.metaKey) &&
      e.shiftKey &&
      e.key === 'C'
    ) {
      clearRequest();
    }

    if (
      (e.ctrlKey || e.metaKey) &&
      e.shiftKey &&
      e.key === 'H'
    ) {
      clearHistory();
    }
  }
);
/* -----------------------------
   INIT DEFAULTS
----------------------------- */

// default sample URL
if (!urlEl.value) {
  urlEl.value =
    'https://jsonplaceholder.typicode.com/posts/1';
}

// default body
if (!bodyEl.value) {
  bodyEl.value = JSON.stringify(
    {
      title: 'LxREST',
      body: 'Single HTML REST Client',
      userId: 1
    },
    null,
    2
  );
}

/* -----------------------------
   INIT HEADERS
----------------------------- */

if (
  document.querySelectorAll(
    '#headersContainer .key-value'
  ).length === 0
) {
  addHeader(
    'Content-Type',
    'application/json'
  );

  addHeader(
    'Accept',
    'application/json'
  );
}

/* -----------------------------
   INIT PARAMS
----------------------------- */

if (
  document.querySelectorAll(
    '#paramsContainer .key-value'
  ).length === 0
) {
  addParam();
}

/* -----------------------------
   REQUEST COUNTER
----------------------------- */

const requestCounter =
  document.createElement('div');

requestCounter.style.cssText = `
  position:fixed;
  left:20px;
  bottom:20px;
  background:rgba(15,23,42,.95);
  border:1px solid var(--border);
  padding:10px 14px;
  border-radius:12px;
  font-size:12px;
  z-index:999;
`;

requestCounter.innerHTML = `
  Requests:
  <strong id="requestCount">0</strong>
`;

document.body.appendChild(
  requestCounter
);

/* -----------------------------
   REQUEST LOGGER
----------------------------- */

const originalFetch = window.fetch;

window.fetch = async (
  ...args
) => {
  const countEl =
    document.getElementById(
      'requestCount'
    );

  countEl.innerText =
    parseInt(
      countEl.innerText
    ) + 1;

  return originalFetch(...args);
};

/* -----------------------------
   LATENCY INDICATOR
----------------------------- */

function latencyColor(ms) {
  if (ms < 300)
    return '#22c55e';

  if (ms < 1000)
    return '#f59e0b';

  return '#ef4444';
}

function updateLatency(ms) {
  timeBox.style.color =
    latencyColor(ms);
}

/* -----------------------------
   AUTO URL NORMALIZER
----------------------------- */

urlEl.addEventListener(
  'blur',
  () => {
    let value =
      urlEl.value.trim();

    if (
      value &&
      !value.startsWith(
        'http://'
      ) &&
      !value.startsWith(
        'https://'
      )
    ) {
