function parseQueryParams(url) {
  try {
    const parsed =
      new URL(url);

    const params =
      parsed.searchParams;

    document.getElementById(
      'paramsContainer'
    ).innerHTML = '';

    params.forEach(
      (value, key) => {
        addParam(
          key,
          value
        );
      }
    );
  } catch {}
}

urlEl.addEventListener(
  'change',
  e => {
    parseQueryParams(
      e.target.value
    );
  }
);

