      (e.ctrlKey || e.metaKey) &&
      e.shiftKey &&
      e.key.toLowerCase() === 'd'
    ) {
      const opened =
        devPanel.style.display ===
        'block';

      devPanel.style.display =
        opened
          ? 'none'
          : 'block';

