/* -----------------------------
   FETCH INTERCEPTOR
----------------------------- */

const nativeFetch =
  window.fetch;

window.fetch = async (
  ...args
) => {
  const start =
    performance.now();

  devLog(
    'Request',
    {
      url: args[0],
      options: args[1]
    }
  );

  try {
    const response =
      await nativeFetch(...args);

    const cloned =
      response.clone();

    const text =
      await cloned.text();

    const end =
      performance.now();

    updateLatency(
      Math.round(
        end - start
      )
    );

    updateStats(
      Math.round(
        end - start
      )
    );

    devLog(
      'Response',
      {
        status:
          response.status,
        elapsed:
          Math.round(
            end - start
          ) + ' ms',
        body:
          text.slice(
            0,
            2000
          )
      }
    );

    return response;
  } catch (err) {
    devLog(
      'Error',
      err.message
    );

    throw err;
  }
};

