      <div id="respBodyTab" class="tab-content active">
        <pre id="responseBody">// Waiting for request...</pre>
      </div>

      <div id="respHeadersTab" class="tab-content">
        <pre id="responseHeaders">// No headers</pre>
      </div>

      <div id="respPreviewTab" class="tab-content">
        <iframe id="previewFrame" class="preview-frame"></iframe>
      </div>
    </section>
  </main>
