<div id="toast">Message</div>

<script>
  const $ = id => document.getElementById(id);

  // State
  let history = JSON.parse(localStorage.getItem('lxrest_history') || '[]');
  let currentController = null;

  /* -----------------------------
     UI Initialization
  ----------------------------- */
  function init() {
    setupTabs();
    renderHistory();
    addKVRow('headersList', 'Content-Type', 'application/json');
    addKVRow('paramsList');

    $('sendBtn').onclick = executeRequest;

    // Auto-save input to memory (optional UX)
    ['url', 'body'].forEach(id => {
      $(id).addEventListener('input', () => {
        localStorage.setItem(`lxrest_draft_${id}`, $(id).value);
      });
      const saved = localStorage.getItem(`lxrest_draft_${id}`);
      if (saved) $(id).value = saved;
    });
  }

  /* -----------------------------
     Tabs System
  ----------------------------- */
  function setupTabs() {
    document.querySelectorAll('.tab').forEach(tab => {
      tab.onclick = () => {
        const container = tab.closest('.tabs').nextElementSibling.parentElement;
        const target = tab.dataset.target;

        // Deactivate all in this group
        tab.parentElement.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        container.querySelectorAll('.tab-content').forEach(c => {
          if (c.parentElement === container) c.classList.remove('active');
        });

        // Activate target
        tab.classList.add('active');
        $(target).classList.add('active');
      };
    });
  }

  /* -----------------------------
     Key Value Editor
  ----------------------------- */
  function addKVRow(listId, key = '', value = '') {
    const list = $(listId);
    const row = document.createElement('div');
    row.className = 'kv-row';
    row.innerHTML = `
      <input type="text" placeholder="Key" value="${key}">
      <input type="text" placeholder="Value" value="${value}">
      <button class="secondary" style="padding: 0 10px;" onclick="this.parentElement.remove()">×</button>
    `;
    list.appendChild(row);
  }

  function collectKV(listId) {
    const data = {};
    document.querySelectorAll(`#${listId} .kv-row`).forEach(row => {
      const inputs = row.querySelectorAll('input');
      const k = inputs[0].value.trim();
      const v = inputs[1].value.trim();
      if (k) data[k] = v;
    });
    return data;
  }

  /* -----------------------------
     Auth Handling
  ----------------------------- */
  function toggleAuthFields() {
    const type = $('authType').value;
    $('authBearer').classList.toggle('hidden', type !== 'bearer');
    $('authBasic').classList.toggle('hidden', type !== 'basic');
  }

  /* -----------------------------
     Core Logic
  ----------------------------- */
  async function executeRequest() {
    const method = $('method').value;
    const urlRaw = $('url').value.trim();
    const body = $('body').value.trim();

    if (!urlRaw) return showToast('URL is required');

    // UI State: Loading
    const sendBtn = $('sendBtn');
    sendBtn.disabled = true;
    sendBtn.innerText = 'Sending...';
    $('responseBody').innerText = '// Loading...';

    if (currentController) currentController.abort();
    currentController = new AbortController();

    const startTime = performance.now();

    try {
      const url = new URL(urlRaw.startsWith('http') ? urlRaw : `https://${urlRaw}`);
      const params = collectKV('paramsList');
      Object.entries(params).forEach(([k, v]) => url.searchParams.append(k, v));

      const headers = collectKV('headersList');

      // Apply Auth
      const authType = $('authType').value;
      if (authType === 'bearer') {
        headers['Authorization'] = `Bearer ${$('bearerToken').value.trim()}`;
      } else if (authType === 'basic') {
        const creds = btoa(`${$('basicUser').value}:${$('basicPass').value}`);
        headers['Authorization'] = `Basic ${creds}`;
      }

      const options = {
        method,
        headers,
        signal: currentController.signal
      };

      if (!['GET', 'HEAD'].includes(method) && body) {
        options.body = body;
      }

      const response = await fetch(url, options);
      const endTime = performance.now();
      const duration = Math.round(endTime - startTime);

      const responseText = await response.text();
      const size = new TextEncoder().encode(responseText).length;

      renderResponse(response, responseText, duration, size);
      saveToHistory(method, url.toString());

    } catch (err) {
      if (err.name === 'AbortError') return;
      $('responseBody').innerText = `// Error: ${err.message}`;
      showToast('Request Failed');
    } finally {
      sendBtn.disabled = false;
      sendBtn.innerText = 'Send';
      currentController = null;
    }
  }

  function renderResponse(res, text, duration, size) {
    // Meta
    const statusLabel = $('statusLabel');
    statusLabel.innerText = `${res.status} ${res.statusText}`;
    statusLabel.className = `status-badge ${res.ok ? 'status-ok' : 'status-err'}`;
    statusLabel.classList.remove('hidden');

    $('timeLabel').innerText = `${duration}ms`;
    $('timeLabel').classList.remove('hidden');

    $('sizeLabel').innerText = formatSize(size);
    $('sizeLabel').classList.remove('hidden');

    // Body
    try {
      const json = JSON.parse(text);
      $('responseBody').innerText = JSON.stringify(json, null, 2);
    } catch {
      $('responseBody').innerText = text || '// Empty Response';
    }

    // Headers
    let headerStr = '';
    res.headers.forEach((v, k) => headerStr += `${k}: ${v}\n`);
    $('responseHeaders').innerText = headerStr;

    // Preview
    const contentType = res.headers.get('content-type') || '';
    if (contentType.includes('text/html')) {
      $('previewFrame').srcdoc = text;
    } else {
      $('previewFrame').srcdoc = '<html><body style="background:#0f172a; color:#94a3b8; font-family:sans-serif; display:flex; align-items:center; justify-content:center; height:100vh;">Preview not available for this content type</body></html>';
    }
  }

  /* -----------------------------
     History
  ----------------------------- */
  function saveToHistory(method, url) {
    const item = { method, url, timestamp: Date.now() };
    // Prevent duplicates at top
    if (history[0]?.url === url && history[0]?.method === method) return;

    history.unshift(item);
    history = history.slice(0, 50); // Keep last 50
    localStorage.setItem('lxrest_history', JSON.stringify(history));
    renderHistory();
  }

  function renderHistory() {
    const list = $('historyList');
    list.innerHTML = history.length ? '' : '<div style="color:var(--muted); font-size:12px; text-align:center; margin-top:20px;">No history yet</div>';

    history.forEach(item => {
      const el = document.createElement('div');
      el.className = 'history-item';
      el.innerHTML = `
        <span class="method" style="color: ${getMethodColor(item.method)}">${item.method}</span>
        <span class="url">${item.url}</span>
      `;
      el.onclick = () => loadHistoryItem(item);
      list.appendChild(el);
    });
  }

  function loadHistoryItem(item) {
    $('method').value = item.method;
    $('url').value = item.url;
    // Note: We don't save body/headers in history to keep storage light, 
    // but a more robust version could.
    showToast('Loaded from history');
  }

  function clearHistory() {
    if (confirm('Clear all history?')) {
      history = [];
      localStorage.setItem('lxrest_history', '[]');
      renderHistory();
    }
  }

  /* -----------------------------
     Utilities
  ----------------------------- */
  function beautifyJSON() {
    try {
      const val = $('body').value.trim();
      if (!val) return;
      $('body').value = JSON.stringify(JSON.parse(val), null, 2);
    } catch {
      showToast('Invalid JSON');
    }
  }

  function clearRequest() {
    $('url').value = '';
    $('body').value = '';
    $('paramsList').innerHTML = '';
    $('headersList').innerHTML = '';
    addKVRow('headersList', 'Content-Type', 'application/json');
    addKVRow('paramsList');
    showToast('Cleared');
  }

  function copyAsCurl() {
    const method = $('method').value;
    const url = $('url').value;
    const headers = collectKV('headersList');
    const body = $('body').value.trim();

    let curl = `curl -X ${method} "${url}"`;
    Object.entries(headers).forEach(([k, v]) => {
      curl += ` -H "${k}: ${v}"`;
    });
    if (body && method !== 'GET') {
      curl += ` -d '${body.replace(/'/g, "'\\''")}'`;
    }

    navigator.clipboard.writeText(curl).then(() => showToast('cURL Copied!'));
  }

  function showToast(msg) {
    const t = $('toast');
    t.innerText = msg;
    t.classList.add('show');
    setTimeout(() => t.classList.remove('show'), 3000);
  }

  function formatSize(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  function getMethodColor(m) {
    const colors = {
      GET: '#10b981',
      POST: '#38bdf8',
      PUT: '#fbbf24',
      PATCH: '#a855f7',
      DELETE: '#ef4444'
    };
    return colors[m] || 'var(--muted)';
  }

  // Initialize
  init();
</script>
</body>
</html>

