    .panel-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--muted);
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }

    /* Controls */
    .request-bar {
      display: flex;
      gap: 12px;
      margin-bottom: 20px;
    }

    select, input, textarea {
      background: var(--bg);
      border: 1px solid var(--border);
