      padding: 10px 14px;
      border-radius: 8px;
      font-family: inherit;
      font-size: 14px;
      outline: none;
      transition: border-color 0.2s;
    }

    select:focus, input:focus, textarea:focus {
      border-color: var(--accent);
    }

    .method-select { width: 120px; font-weight: 600; }
    .url-input { flex: 1; }

    button {
      background: var(--accent);
