    .kv-row {
      display: flex;
      gap: 8px;
      margin-bottom: 8px;
    }

    .kv-row input { flex: 1; font-size: 12px; padding: 8px 12px; }

    /* Response Meta */
    .response-meta {
      display: flex;
      gap: 16px;
      font-size: 12px;
      font-family: 'JetBrains Mono', 'Fira Code', monospace;
    }

    .status-badge {
      padding: 2px 8px;
      border-radius: 4px;
      font-weight: 700;
    }

    .status-ok { background: #10b98122; color: #10b981; }
    .status-err { background: #ef444422; color: #ef4444; }

    pre {
