<script>
  const $ = id => document.getElementById(id);

  // State
  let history = JSON.parse(localStorage.getItem('lxrest_history') || '[]');
  let collections = JSON.parse(localStorage.getItem('lxrest_collections') || '[]');
  let environments = JSON.parse(localStorage.getItem('lxrest_env') || '{"Default":{}}');
  let currentEnv = localStorage.getItem('lxrest_current_env') || 'Default';
  let sideActive = 'history';
  let currentController = null;
  let ws = null;

  /* -----------------------------
     Initialization
  ----------------------------- */
  function init() {
    setupTabs();
    setupSidebarTabs();
    renderSidebar();
    addKVRow('headersList', 'Content-Type', 'application/json');
    addKVRow('paramsList');

    $('sendBtn').onclick = executeRequest;

    // Auto-resize textareas
    document.querySelectorAll('textarea').forEach(el => {
      el.addEventListener('input', () => {
        el.style.height = 'auto';
        el.style.height = el.scrollHeight + 'px';
      });
    });

    // Shortcuts
    window.onkeydown = e => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') executeRequest();
      if ((e.ctrlKey || e.metaKey) && e.key === 'b') beautifyJSON();
    };
  }

  /* -----------------------------
     Environment Replacement
  ----------------------------- */
  function replaceEnv(text) {
    if (!text) return text;
    const envData = environments[currentEnv] || {};
    return text.replace(/\{\{(.*?)\}\}/g, (match, key) => {
      return envData[key.trim()] !== undefined ? envData[key.trim()] : match;
    });
  }

  /* -----------------------------
     Tabs System
  ----------------------------- */
  function setupTabs() {
    document.querySelectorAll('.tab').forEach(tab => {
      tab.onclick = () => {
        const parent = tab.closest('.tabs');
        const container = parent.nextElementSibling.parentElement;
        const target = tab.dataset.target;
        parent.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        container.querySelectorAll('.tab-content').forEach(c => {
          if (c.parentElement === container) c.classList.remove('active');
        });
        tab.classList.add('active');
        $(target).classList.add('active');
      };
    });
  }

  function setupSidebarTabs() {
    document.querySelectorAll('.sidebar-tab').forEach(tab => {
      tab.onclick = () => {
        document.querySelectorAll('.sidebar-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        sideActive = tab.dataset.side;
        renderSidebar();
      };
    });
  }

  /* -----------------------------
     Sidebar Rendering
  ----------------------------- */
  function renderSidebar() {
    const cont = $('sideContent');
    cont.innerHTML = '';

    if (sideActive === 'history') {
      if (!history.length) cont.innerHTML = '<div style="color:var(--bruno-text-muted); text-align:center; margin-top:20px; font-size:12px;">No history</div>';
      history.forEach((item, idx) => {
        const el = createListItem(item.method, item.url, () => loadRequest(item));
        cont.appendChild(el);
      });
    } else if (sideActive === 'collections') {
      if (!collections.length) cont.innerHTML = '<div style="color:var(--bruno-text-muted); text-align:center; margin-top:20px; font-size:12px;">No collections</div>';
      collections.forEach((item, idx) => {
        const el = createListItem(item.method, item.name || item.url, () => loadRequest(item));
        cont.appendChild(el);
      });
    } else if (sideActive === 'env') {
      renderEnvEditor(cont);
    }
  }

  function createListItem(method, title, onclick) {
    const el = document.createElement('div');
    el.className = 'list-item';
    el.innerHTML = `
      <span class="method" style="color: ${getMethodColor(method)}">${method}</span>
      <span class="title">${title}</span>
    `;
    el.onclick = onclick;
    return el;
  }

  function renderEnvEditor(container) {
    const envs = Object.keys(environments);
    let html = `<select onchange="switchEnv(this.value)" style="width:100%; margin-bottom:10px;">
      ${envs.map(e => `<option value="${e}" ${e === currentEnv ? 'selected' : ''}>${e}</option>`).join('')}
    </select>
    <div style="font-size:11px; margin-bottom:5px; color:var(--bruno-text-muted);">VARS (JSON)</div>
    <textarea id="envJson" style="width:100%; height:200px; font-size:12px;">${JSON.stringify(environments[currentEnv], null, 2)}</textarea>
    <button class="secondary" style="width:100%; margin-top:5px; font-size:11px;" onclick="saveEnv()">Save Environment</button>
    <button class="secondary" style="width:100%; margin-top:5px; font-size:11px;" onclick="addEnv()">+ New Environment</button>`;
    container.innerHTML = html;
  }

  /* -----------------------------
     Core Network Logic
  ----------------------------- */
  async function executeRequest() {
    const method = $('method').value;
    const urlRaw = replaceEnv($('url').value.trim());
    const bodyRaw = replaceEnv($('body').value.trim());

    if (!urlRaw) return showToast('URL is required');

    const sendBtn = $('sendBtn');
    sendBtn.disabled = true;
    sendBtn.innerText = 'Sending...';
    $('responseBody').innerText = '// Loading...';

...
    const startTime = performance.now();

    try {
      const url = new URL(urlRaw.startsWith('http') ? urlRaw : `https://${urlRaw}`);
      const params = collectKV('paramsList');
      Object.entries(params).forEach(([k, v]) => url.searchParams.append(replaceEnv(k), replaceEnv(v)));

      const headers = collectKV('headersList');
      // Replace env in headers
      const finalHeaders = {};
      Object.entries(headers).forEach(([k, v]) => finalHeaders[replaceEnv(k)] = replaceEnv(v));

      const authType = $('authType').value;
      if (authType === 'bearer') {
        finalHeaders['Authorization'] = `Bearer ${replaceEnv($('bearerToken').value.trim())}`;
      } else if (authType === 'basic') {
        const creds = btoa(`${replaceEnv($('basicUser').value)}:${replaceEnv($('basicPass').value)}`);
        finalHeaders['Authorization'] = `Basic ${creds}`;
      }

      const options = { method, headers: finalHeaders, signal: currentController.signal };
      if (!['GET', 'HEAD'].includes(method) && bodyRaw) options.body = bodyRaw;

      const response = await fetch(url, options);
      const duration = Math.round(performance.now() - startTime);
      const text = await response.text();
      const size = new TextEncoder().encode(text).length;

      renderResponse(response, text, duration, size);
      saveToHistory(method, url.toString());

    } catch (err) {
      if (err.name === 'AbortError') return;
      $('responseBody').innerText = `// Error: ${err.message}`;
      showToast('Network Error');
    } finally {
      sendBtn.disabled = false;
      sendBtn.innerText = 'Send';
    }
  }

  function renderResponse(res, text, duration, size) {
    const sl = $('statusLabel');
    sl.innerText = `${res.status} ${res.statusText}`;
    sl.className = `status-badge ${res.ok ? 'status-ok' : 'status-err'}`;
    sl.classList.remove('hidden');
    $('timeLabel').innerText = `${duration}ms`;
    $('timeLabel').classList.remove('hidden');
    $('sizeLabel').innerText = formatSize(size);
    $('sizeLabel').classList.remove('hidden');

    try {
      const json = JSON.parse(text);
      $('responseBody').innerText = JSON.stringify(json, null, 2);
    } catch {
      $('responseBody').innerText = text || '// Empty body';
    }

    let hStr = '';
    res.headers.forEach((v, k) => hStr += `${k}: ${v}\n`);
    $('responseHeaders').innerText = hStr || '// No headers';

    const ct = res.headers.get('content-type') || '';
    if (ct.includes('text/html')) $('previewFrame').srcdoc = text;
    else $('previewFrame').srcdoc = '<html><body style="background:#0F172A; color:#94A3B8; font-family:sans-serif; display:flex; align-items:center; justify-content:center; height:100vh;">Preview only for HTML</body></html>';
  }

  /* -----------------------------
     Save/Load State
  ----------------------------- */
  function saveToHistory(method, url) {
    const item = { method, url, timestamp: Date.now() };
    if (history[0]?.url === url && history[0]?.method === method) return;
    history.unshift(item);
    history = history.slice(0, 30);
    localStorage.setItem('lxrest_history', JSON.stringify(history));
    if (sideActive === 'history') renderSidebar();
  }

  function saveToCollection() {
    const name = prompt('Request Name:', $('url').value);
    if (!name) return;
    const item = { 
      name, 
      method: $('method').value, 
      url: $('url').value, 
      body: $('body').value,
      headers: collectKV('headersList'),
      params: collectKV('paramsList')
    };
    collections.unshift(item);
    localStorage.setItem('lxrest_collections', JSON.stringify(collections));
    showToast('Saved to Collections');
    if (sideActive === 'collections') renderSidebar();
  }

  function loadRequest(item) {
    $('method').value = item.method;
    $('url').value = item.url;
    $('body').value = item.body || '';
    if (item.params) {
      $('paramsList').innerHTML = '';
      Object.entries(item.params).forEach(([k, v]) => addKVRow('paramsList', k, v));
    }
    if (item.headers) {
      $('headersList').innerHTML = '';
      Object.entries(item.headers).forEach(([k, v]) => addKVRow('headersList', k, v));
    }
    showToast('Request loaded');
  }

  /* -----------------------------
     Environment Logic
  ----------------------------- */
  function switchEnv(name) {
    currentEnv = name;
    localStorage.setItem('lxrest_current_env', name);
    renderSidebar();
  }

  function saveEnv() {
    try {
      environments[currentEnv] = JSON.parse($('envJson').value);
      localStorage.setItem('lxrest_env', JSON.stringify(environments));
      showToast('Environment Saved');
    } catch { showToast('Invalid JSON'); }
  }

  function addEnv() {
    const name = prompt('Environment Name:');
    if (!name) return;
    environments[name] = {};
    switchEnv(name);
  }

  /* -----------------------------
     WebSocket Logic
  ----------------------------- */
  function toggleWebSocket() {
    $('restClient').classList.toggle('hidden');
    $('wsClient').classList.toggle('hidden');
  }

  function wsConnect() {
    const url = $('wsUrl').value;
    if (ws) ws.close();
    ws = new WebSocket(url);
    wsLog('Connecting to ' + url, 'sys');
    ws.onopen = () => { wsLog('Connected', 'sys'); $('wsConnectBtn').innerText = 'Disconnect'; $('wsSendBtn').disabled = false; };
    ws.onclose = () => { wsLog('Disconnected', 'sys'); $('wsConnectBtn').innerText = 'Connect'; $('wsSendBtn').disabled = true; ws = null; };
    ws.onmessage = (e) => wsLog(e.data, 'in');
    ws.onerror = (e) => wsLog('Error: ' + e.message, 'sys');
  }

  function wsSend() {
    const msg = $('wsMsg').value;
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(msg);
      wsLog(msg, 'out');
      $('wsMsg').value = '';
    }
  }

  function wsLog(msg, type) {
    const div = document.createElement('div');
    div.className = `ws-msg ws-${type}`;
    div.innerText = `[${new Date().toLocaleTimeString()}] ${msg}`;
    $('wsLog').appendChild(div);
    $('wsLog').scrollTop = $('wsLog').scrollHeight;
  }

  /* -----------------------------
     KV Row Helper
  ----------------------------- */
  function addKVRow(listId, key = '', value = '') {
    const row = document.createElement('div');
    row.className = 'kv-row';
    row.innerHTML = `<input type="text" placeholder="Key" value="${key}"><input type="text" placeholder="Value" value="${value}"><button class="secondary" onclick="this.parentElement.remove()">×</button>`;
    $(listId).appendChild(row);
  }

  function collectKV(listId) {
    const res = {};
    document.querySelectorAll(`#${listId} .kv-row`).forEach(row => {
      const inputs = row.querySelectorAll('input');
      if (inputs[0].value) res[inputs[0].value] = inputs[1].value;
    });
    return res;
  }

  /* -----------------------------
     Utility
  ----------------------------- */
  function beautifyJSON() {
    try {
      const b = $('body');
      b.value = JSON.stringify(JSON.parse(b.value), null, 2);
    } catch { showToast('Invalid JSON'); }
  }

  function copyAsCurl() {
    const method = $('method').value;
    const url = $('url').value;
    const headers = collectKV('headersList');
    let curl = `curl -X ${method} "${url}"`;
    Object.entries(headers).forEach(([k, v]) => curl += ` -H "${k}: ${v}"`);
    const body = $('body').value.trim();
    if (body && method !== 'GET') curl += ` -d '${body.replace(/'/g, "'\\''")}'`;
    navigator.clipboard.writeText(curl).then(() => showToast('cURL copied!'));
  }

  function showToast(m) {
    const t = $('toast'); t.innerText = m; t.classList.add('show');
    setTimeout(() => t.classList.remove('show'), 3000);
  }

  function formatSize(b) {
    if (b < 1024) return b + ' B';
    if (b < 1048576) return (b/1024).toFixed(1) + ' KB';
    return (b/1048576).toFixed(1) + ' MB';
  }

  function getMethodColor(m) {
    return { GET: '#10b981', POST: '#6C63FF', PUT: '#fbbf24', PATCH: '#a855f7', DELETE: '#ef4444' }[m] || '#94A3B8';
  }

  function clearSidebar() {
    if (confirm('Clear ' + sideActive + '?')) {
      if (sideActive === 'history') history = [];
      else if (sideActive === 'collections') collections = [];
      localStorage.setItem(`lxrest_${sideActive}`, '[]');
      renderSidebar();
    }
  }

  function toggleAuthFields() {
    const type = $('authType').value;
    $('authBearer').classList.toggle('hidden', type !== 'bearer');
    $('authBasic').classList.toggle('hidden', type !== 'basic');
  }

  init();
</script>
</body>
</html>

